namespace DbMigrator.SeedData;

public static class ExpensesSeed
{
    public static async Task<ExpensesSeedSummary> SeedAsync(SeedContext context, CancellationToken cancellationToken)
    {
        var category = SeedIds.Child(context.Tenant.Id, "expenses-category", 1);
        var version = SeedIds.Child(context.Tenant.Id, "expenses-category-version", 1);
        await context.ExecuteAsync("insert into business_expenses.expense_category(tenant_id,id,legal_entity_id,code,name,status,created_at) values($1,$2,$3,'TRAVEL','تنقلات ومهمات عمل','Active',$4) on conflict(tenant_id,legal_entity_id,code) do update set name=excluded.name,status='Active'", cancellationToken, context.Tenant.Id, category, context.EntityId, context.AsOf);
        await context.ExecuteAsync("insert into business_expenses.expense_category_version(tenant_id,id,category_id,version,status,requires_receipt,receipt_threshold,effective_from) values($1,$2,$3,1,'Published',true,500,'2025-01-01') on conflict(tenant_id,category_id,version) do nothing", cancellationToken, context.Tenant.Id, version, category);

        // Published Rate Policies
        var mileagePolicyId = SeedIds.Child(context.Tenant.Id, "expenses-rate-mileage", 1);
        await context.ExecuteAsync("insert into business_expenses.expense_rate_policy(tenant_id,id,legal_entity_id,kind,version,status,effective_from,vehicle_type,currency_code,rate,created_at) values($1,$2,$3,'Mileage',1,'Published','2025-01-01','StandardCar','EGP',5.0000,$4) on conflict(tenant_id,id) do nothing", cancellationToken, context.Tenant.Id, mileagePolicyId, context.EntityId, context.AsOf);

        var perDiemPolicyId = SeedIds.Child(context.Tenant.Id, "expenses-rate-perdiem", 1);
        await context.ExecuteAsync("insert into business_expenses.expense_rate_policy(tenant_id,id,legal_entity_id,kind,version,status,effective_from,location_code,currency_code,rate,breakfast_reduction,lunch_reduction,dinner_reduction,created_at) values($1,$2,$3,'PerDiem',1,'Published','2025-01-01','CAIRO','EGP',300.0000,50.0000,100.0000,100.0000,$4) on conflict(tenant_id,id) do nothing", cancellationToken, context.Tenant.Id, perDiemPolicyId, context.EntityId, context.AsOf);

        var draft = SeedIds.Child(context.Tenant.Id, "expenses-draft", 1);
        var submitted = SeedIds.Child(context.Tenant.Id, "expenses-submitted", 2);
        var finalized = SeedIds.Child(context.Tenant.Id, "expenses-finalized", 3);
        var employee = SeedIds.Stable($"{context.Tenant.Id:D}:hr:employee:0001");
        var adminUser = SeedIds.Identity(context.Tenant.Id, "admin");

        await context.ExecuteAsync("insert into business_expenses.expense(tenant_id,id,legal_entity_id,employee_id,merchant_name,expense_date,amount,currency_code,payment_source,category_version_id,expense_state,approval_state,accounting_state,settlement_state,evidence_state,policy_state,business_purpose,description,created_at,updated_at) values($1,$2,$3,$4,'مواصلات القاهرة',$5,180,'EGP','EmployeePaid',$6,'Draft','Pending','NotFinalized','NotSettled','Missing','NotEvaluated','مهمة عميل','مصروف مسودة',$7,$7) on conflict(tenant_id,id) do nothing", cancellationToken, context.Tenant.Id, draft, context.EntityId, employee, DateOnly.FromDateTime(context.AsOf.UtcDateTime.Date), version, context.AsOf);
        await context.ExecuteAsync("insert into business_expenses.expense(tenant_id,id,legal_entity_id,employee_id,merchant_name,expense_date,amount,currency_code,payment_source,category_version_id,expense_state,approval_state,accounting_state,settlement_state,evidence_state,policy_state,business_purpose,description,created_at,updated_at) values($1,$2,$3,$4,'فندق النيل',$5,1650,'EGP','EmployeePaid',$6,'Submitted','Pending','NotFinalized','NotSettled','Verified','Passed','مهمة عمل','بانتظار اعتماد المدير',$7,$7) on conflict(tenant_id,id) do nothing", cancellationToken, context.Tenant.Id, submitted, context.EntityId, employee, DateOnly.FromDateTime(context.AsOf.UtcDateTime.Date.AddDays(-1)), version, context.AsOf);
        await context.ExecuteAsync("insert into business_expenses.expense(tenant_id,id,legal_entity_id,employee_id,merchant_name,expense_date,amount,currency_code,payment_source,category_version_id,expense_state,approval_state,accounting_state,settlement_state,evidence_state,policy_state,business_purpose,description,finalized_at,created_at,updated_at) values($1,$2,$3,$4,'تاكسي الشركة',$5,320,'EGP','EmployeePaid',$6,'Finalized','Approved','Pending','ReimbursementPending','Verified','Passed','اجتماع عميل','التزام سداد موظف',$7,$7,$7) on conflict(tenant_id,id) do update set expense_state=excluded.expense_state, approval_state=excluded.approval_state, accounting_state=excluded.accounting_state, settlement_state=excluded.settlement_state, evidence_state=excluded.evidence_state, policy_state=excluded.policy_state", cancellationToken, context.Tenant.Id, finalized, context.EntityId, employee, DateOnly.FromDateTime(context.AsOf.UtcDateTime.Date.AddDays(-2)), version, context.AsOf);

        // The seeded finalized expense is also a posted financial fact.  Keeping the
        // owner row and its Ledger journal together makes the development seed useful
        // for Planning reconciliation instead of exposing an impossible "posted"
        // expense with no authoritative accounting evidence.
        var finalizedDate = DateOnly.FromDateTime(context.AsOf.UtcDateTime.Date.AddDays(-2));
        var accountingPeriod = await context.ScalarAsync<Guid>("select id from finance_ledger.accounting_period where tenant_id=$1 and legal_entity_id=$2 and start_date <= $3 and end_date >= $3 and status='Open' order by start_date desc limit 1", cancellationToken, context.Tenant.Id, context.EntityId, finalizedDate);
        var configurationVersion = await context.ScalarAsync<Guid>("select active_configuration_version_id from finance_ledger.ledger_entity_configuration where tenant_id=$1 and legal_entity_id=$2", cancellationToken, context.Tenant.Id, context.EntityId);
        var postingRuleVersion = await context.ScalarAsync<Guid>("select v.id from finance_ledger.posting_rule r join finance_ledger.posting_rule_version v on v.tenant_id=r.tenant_id and v.legal_entity_id=r.legal_entity_id and v.posting_rule_id=r.id and v.version_number=1 and v.status='Active' where r.tenant_id=$1 and r.legal_entity_id=$2 and r.fact_type='ExpenseRecognized' and r.status='Active'", cancellationToken, context.Tenant.Id, context.EntityId);
        var generalJournal = await context.ScalarAsync<Guid>("select id from finance_ledger.journal where tenant_id=$1 and legal_entity_id=$2 and code='GENERAL' and status='Active'", cancellationToken, context.Tenant.Id, context.EntityId);
        var expenseAccount = await context.ScalarAsync<Guid>("select a.id from finance_ledger.account a join finance_ledger.account_mapping_version mv on mv.tenant_id=a.tenant_id and mv.legal_entity_id=a.legal_entity_id and mv.target_account_id=a.id join finance_ledger.account_mapping m on m.tenant_id=mv.tenant_id and m.legal_entity_id=mv.legal_entity_id and m.id=mv.mapping_id join finance_ledger.account_role r on r.tenant_id=m.tenant_id and r.legal_entity_id=m.legal_entity_id and r.id=m.role_id where a.tenant_id=$1 and a.legal_entity_id=$2 and r.code='PurchaseExpense' and mv.status='Active' order by mv.effective_from desc limit 1", cancellationToken, context.Tenant.Id, context.EntityId);
        var reimbursementAccount = await context.ScalarAsync<Guid>("select a.id from finance_ledger.account a join finance_ledger.account_mapping_version mv on mv.tenant_id=a.tenant_id and mv.legal_entity_id=a.legal_entity_id and mv.target_account_id=a.id join finance_ledger.account_mapping m on m.tenant_id=mv.tenant_id and m.legal_entity_id=mv.legal_entity_id and m.id=mv.mapping_id join finance_ledger.account_role r on r.tenant_id=m.tenant_id and r.legal_entity_id=m.legal_entity_id and r.id=m.role_id where a.tenant_id=$1 and a.legal_entity_id=$2 and r.code='EmployeeReimbursementPayable' and mv.status='Active' order by mv.effective_from desc limit 1", cancellationToken, context.Tenant.Id, context.EntityId);
        var accountingFact = SeedIds.Child(context.Tenant.Id, "expenses-finalized-accounting-fact", 1);
        var journalEntry = SeedIds.Child(context.Tenant.Id, "expenses-finalized-journal-entry", 1);
        var correlation = SeedIds.Child(context.Tenant.Id, "expenses-finalized-correlation", 1);
        await context.ExecuteAsync("insert into finance_ledger.accounting_fact(tenant_id,legal_entity_id,id,fact_type,fact_version,source_module,source_reference,idempotency_key,business_date,posting_date,payload_jsonb,payload_hash,status,correlation_id,actor_id,received_at,posted_at) values($1,$2,$3,'ExpenseRecognized',1,'expenses',$4,$5,$6,$6,'{\"baseAmount\":320,\"baseCurrency\":\"EGP\"}'::jsonb,'seed-expense-recognized','Posted',$7,$8,$9,$9) on conflict(tenant_id,id) do update set status='Posted',source_reference=excluded.source_reference,posted_at=excluded.posted_at", cancellationToken, context.Tenant.Id, context.EntityId, accountingFact, finalized.ToString("D"), $"expense-finalize:{finalized:D}", finalizedDate, correlation, adminUser, context.AsOf);
        await context.ExecuteAsync("insert into finance_ledger.journal_entry(tenant_id,legal_entity_id,id,journal_id,fact_id,source_module,source_reference,entry_number,posting_date,accounting_period_id,fact_type,fact_version,status,currency_code,base_currency_code,posting_rule_version_id,accounting_configuration_version_id,description,correlation_id,actor_id,posted_at) values($1,$2,$3,$4,$5,'expenses',$6,$7,$8,$9,'ExpenseRecognized',1,'Posted','EGP','EGP',$10,$11,'Development seed expense posting',$12,$13,$14) on conflict(tenant_id,id) do update set status='Posted',posted_at=excluded.posted_at", cancellationToken, context.Tenant.Id, context.EntityId, journalEntry, generalJournal, accountingFact, finalized.ToString("D"), $"SEED-EXP-{finalized:N}", finalizedDate, accountingPeriod, postingRuleVersion, configurationVersion, correlation, adminUser, context.AsOf);
        await context.ExecuteAsync("insert into finance_ledger.journal_entry_line(tenant_id,legal_entity_id,id,journal_entry_id,sequence_no,account_id,debit,credit,currency_code,amount,exchange_rate,semantic_role,account_role,transaction_debit,transaction_credit,base_debit,base_credit,exchange_rate_snapshot) values($1,$2,$3,$4,1,$5,320,0,'EGP',320,1,'ExpenseRecognized','PurchaseExpense',320,0,320,0,'{\"rate\":1}'::jsonb),($1,$2,$6,$4,2,$7,0,320,'EGP',320,1,'ExpenseRecognized','EmployeeReimbursementPayable',0,320,0,320,'{\"rate\":1}'::jsonb) on conflict(tenant_id,journal_entry_id,sequence_no) do update set debit=excluded.debit,credit=excluded.credit,base_debit=excluded.base_debit,base_credit=excluded.base_credit", cancellationToken, context.Tenant.Id, context.EntityId, SeedIds.Child(context.Tenant.Id, "expenses-finalized-journal-line", 1), journalEntry, expenseAccount, SeedIds.Child(context.Tenant.Id, "expenses-finalized-journal-line", 2), reimbursementAccount);
        await context.ExecuteAsync("update finance_ledger.accounting_fact set posted_entry_id=$3 where tenant_id=$1 and id=$2", cancellationToken, context.Tenant.Id, accountingFact, journalEntry);
        await context.ExecuteAsync("update business_expenses.expense set accounting_state='Posted',base_currency_code='EGP',base_amount=320,accounting_fact_id=$3,ledger_entry_id=$4 where tenant_id=$1 and id=$2", cancellationToken, context.Tenant.Id, finalized, accountingFact, journalEntry);

        // Platform Approval Request for submitted expense
        var approvalId = SeedIds.Child(context.Tenant.Id, "expenses-approval", 1);
        await context.ExecuteAsync("insert into platform.approval_request(tenant_id,id,legal_entity_id,owner_module,owner_entity_type,owner_entity_id,resource_version,state,requested_by,request_reason,created_at) values($1,$2,$3,'expenses','expense',$4,1,'Pending',$5,'طلب اعتماد مصروف مهمة عمل',$6) on conflict(tenant_id,owner_module,owner_entity_type,owner_entity_id,resource_version) do nothing", cancellationToken, context.Tenant.Id, approvalId, context.EntityId, submitted, adminUser, context.AsOf);
        await context.ExecuteAsync("update business_expenses.expense set approval_request_id=$3 where tenant_id=$1 and id=$2 and approval_request_id is null", cancellationToken, context.Tenant.Id, submitted, approvalId);

        // Corporate Card Transaction
        var cardTxId = SeedIds.Child(context.Tenant.Id, "expenses-card-tx", 1);
        await context.ExecuteAsync("insert into business_expenses.expense_card_transaction(tenant_id,id,legal_entity_id,provider_reference,merchant_name,transaction_date,amount,currency_code,state,employee_id,created_at) values($1,$2,$3,'TX-CARD-9901','محطة وقود النيل',$4,650.0000,'EGP','Unmatched',$5,$6) on conflict(tenant_id,id) do update set state=excluded.state, matched_expense_id=null", cancellationToken, context.Tenant.Id, cardTxId, context.EntityId, DateOnly.FromDateTime(context.AsOf.UtcDateTime.Date.AddDays(-1)), employee, context.AsOf);

        // Business Advance
        var advanceId = SeedIds.Child(context.Tenant.Id, "expenses-advance", 1);
        await context.ExecuteAsync("insert into business_expenses.business_advance(tenant_id,id,legal_entity_id,employee_id,amount,currency_code,issued_amount,applied_amount,returned_amount,state,purpose,created_at,issued_at) values($1,$2,$3,$4,5000.0000,'EGP',5000.0000,0.0000,0.0000,'Issued','سلفة سفر لمعرض الإسكندرية الدولي',$5,$5) on conflict(tenant_id,id) do update set state=excluded.state, issued_amount=excluded.issued_amount, applied_amount=0.0000, returned_amount=0.0000", cancellationToken, context.Tenant.Id, advanceId, context.EntityId, employee, context.AsOf);

        // Reimbursement Obligation
        await context.ExecuteAsync("insert into business_expenses.expense_reimbursement_obligation(tenant_id,id,legal_entity_id,expense_id,employee_id,amount,currency_code,status) values($1,$2,$3,$4,$5,320,'EGP','Pending') on conflict(tenant_id,expense_id) do update set status=excluded.status, settled_amount=0, amount=excluded.amount", cancellationToken, context.Tenant.Id, SeedIds.Child(context.Tenant.Id, "expenses-reimbursement", 1), context.EntityId, finalized, employee);

        return new(1, 3, 1);
    }
}

public sealed record ExpensesSeedSummary(int Categories, int Expenses, int FinalizedExpenses);
